import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as a}from"./app-Bk8M88M6.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/PostgreSQL/02_%E8%BF%9B%E9%98%B6%E7%AF%87/02_%E9%94%81%E6%9C%BA%E5%88%B6.html","title":"锁机制","lang":"zh-CN","frontmatter":{"title":"锁机制","order":2,"category":["数据库","PostgreSQL"],"tag":["PostgreSQL","锁","死锁","行锁","咨询锁"]},"git":{"createdTime":1780573763000,"updatedTime":1780712648000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":7.1,"words":2130},"filePathRelative":"后端开发/数据库/PostgreSQL/02_进阶篇/02_锁机制.md"}`),s={name:`02_锁机制.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="锁机制" tabindex="-1"><a class="header-anchor" href="#锁机制"><span>锁机制</span></a></h1><div class="hint-container tip"><p class="hint-container-title">核心观点</p><p>PostgreSQL 的锁体系从表级到行级、从常规锁到咨询锁，层次分明。PG 的行锁实现尤其独特——<strong>不在磁盘存储锁信息</strong>，而是利用 xmax 字段标记，这使得行锁的成本极低但语义完整。</p></div><h2 id="锁层次总览" tabindex="-1"><a class="header-anchor" href="#锁层次总览"><span>锁层次总览</span></a></h2>`,3),i(d,{code:``}),o[1]||=n(`<h2 id="表级锁" tabindex="-1"><a class="header-anchor" href="#表级锁"><span>表级锁</span></a></h2><h3 id="_8-种锁模式-强度递增" tabindex="-1"><a class="header-anchor" href="#_8-种锁模式-强度递增"><span>8 种锁模式（强度递增）</span></a></h3><table><thead><tr><th>锁模式</th><th>获取方式</th><th>典型场景</th></tr></thead><tbody><tr><td>ACCESS SHARE</td><td><code>SELECT</code></td><td>最轻量，普通查询</td></tr><tr><td>ROW SHARE</td><td><code>SELECT FOR UPDATE/SHARE</code></td><td>准备更新</td></tr><tr><td>ROW EXCLUSIVE</td><td><code>UPDATE / DELETE / INSERT</code></td><td>DML 操作</td></tr><tr><td>SHARE UPDATE EXCLUSIVE</td><td><code>VACUUM / ANALYZE</code></td><td>维护操作</td></tr><tr><td>SHARE</td><td><code>CREATE INDEX</code>（不加 CONCURRENTLY）</td><td>建索引（阻塞写入）</td></tr><tr><td>SHARE ROW EXCLUSIVE</td><td><code>CREATE TRIGGER</code>（某些情况）</td><td>较少见</td></tr><tr><td>EXCLUSIVE</td><td><code>CREATE INDEX CONCURRENTLY</code></td><td>阻塞大部分操作</td></tr><tr><td>ACCESS EXCLUSIVE</td><td><code>ALTER TABLE / DROP TABLE / LOCK TABLE</code></td><td>最重，完全排他</td></tr></tbody></table><h3 id="锁冲突矩阵" tabindex="-1"><a class="header-anchor" href="#锁冲突矩阵"><span>锁冲突矩阵</span></a></h3>`,4),i(d,{code:``}),o[2]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 手动获取表级锁</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">LOCK </span><span style="color:#C678DD;">TABLE</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> ACCESS EXCLUSIVE MODE;  </span><span style="color:#7F848E;font-style:italic;">-- 完全锁表</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 执行操作</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 常见：迁移时锁表防止新数据写入</span></span>
<span class="line"><span style="color:#ABB2BF;">LOCK </span><span style="color:#C678DD;">TABLE</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> SHARE MODE;  </span><span style="color:#7F848E;font-style:italic;">-- 允许读，阻塞写</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="行级锁" tabindex="-1"><a class="header-anchor" href="#行级锁"><span>行级锁</span></a></h2><h3 id="for-update-share-系列" tabindex="-1"><a class="header-anchor" href="#for-update-share-系列"><span>FOR UPDATE / SHARE 系列</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR UPDATE：排他行锁（最常用）</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 锁定该行</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> balance - </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR NO KEY UPDATE：弱排他锁（不阻塞 SELECT FOR SHARE）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- UPDATE 语句默认获取此锁</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> NO</span><span style="color:#C678DD;"> KEY</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 其他会话仍可 SELECT ... FOR KEY SHARE</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR SHARE：共享行锁（读锁）</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#ABB2BF;"> SHARE;  </span><span style="color:#7F848E;font-style:italic;">-- 阻止其他人 FOR UPDATE</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR KEY SHARE：最弱共享锁（仅锁外键引用）</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> KEY</span><span style="color:#ABB2BF;"> SHARE;  </span><span style="color:#7F848E;font-style:italic;">-- 阻止 DELETE，允许 UPDATE 非键列</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="nowait-和-skip-locked" tabindex="-1"><a class="header-anchor" href="#nowait-和-skip-locked"><span>NOWAIT 和 SKIP LOCKED</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR UPDATE NOWAIT：锁不到就立即报错，不等</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#C678DD;"> NOWAIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 如果行已被锁：ERROR: could not obtain lock on row</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR UPDATE SKIP LOCKED：跳过已锁的行</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;pending&#39;</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> id</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"><span style="color:#C678DD;">FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#C678DD;"> SKIP</span><span style="color:#ABB2BF;"> LOCKED;  </span><span style="color:#7F848E;font-style:italic;">-- 跳过被锁的行，返回未锁的</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 适合：工作队列、并发任务分配</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">SKIP LOCKED 是并发队列的最佳实践</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 工作队列：多个 worker 并发领取任务</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> tasks</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;processing&#39;</span><span style="color:#ABB2BF;">, worker_id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> tasks</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#C678DD;"> status</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;pending&#39;</span></span>
<span class="line"><span style="color:#C678DD;">    ORDER BY</span><span style="color:#C678DD;"> priority DESC</span><span style="color:#ABB2BF;">, id</span></span>
<span class="line"><span style="color:#C678DD;">    LIMIT</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"><span style="color:#C678DD;">    FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#C678DD;"> SKIP</span><span style="color:#ABB2BF;"> LOCKED</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>不需要应用层分布式锁，数据库原生支持并发安全的任务分配。</p></div><h3 id="行锁的实现原理" tabindex="-1"><a class="header-anchor" href="#行锁的实现原理"><span>行锁的实现原理</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- PG 的行锁不在磁盘存储锁信息！</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 而是利用 tuple 的 xmax 字段：</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. FOR UPDATE：将 xmax 设置为当前事务 ID</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--    其他事务看到 xmax != 0，知道该行被锁</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 释放锁：事务提交时，xmax 保持不变（标记删除）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--    事务回滚时，xmax 被清除</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 验证：</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> txid_current();  </span><span style="color:#7F848E;font-style:italic;">-- 假设 200</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 另一个会话查看</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, xmin, xmax </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- id | xmin | xmax</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ----+------+-----</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  1 |  100 |  200   ← xmax=200 表示被 txn 200 锁定/删除</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">ROLLBACK</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 回滚后 xmax 恢复为 0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="死锁检测" tabindex="-1"><a class="header-anchor" href="#死锁检测"><span>死锁检测</span></a></h2>`,10),i(d,{code:``}),o[3]||=n(`<div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 死锁演示</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> balance - </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 锁行 1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 B（同时）</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> balance - </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 锁行 2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A（继续）</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> balance + </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 等待行 2...</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 B（继续）</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> balance + </span><span style="color:#D19A66;">100</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 死锁！</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ERROR: deadlock detected</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- DETAIL: Process 12345 waits for ShareLock on transaction 200; blocked by process 12346.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 死锁检测配置</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW deadlock_timeout;  </span><span style="color:#7F848E;font-style:italic;">-- 默认 1s，多久检查一次死锁</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看当前锁等待</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> blocked</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> blocked_pid,</span></span>
<span class="line"><span style="color:#D19A66;">       blocked</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> blocked_query,</span></span>
<span class="line"><span style="color:#D19A66;">       blocking</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> blocking_pid,</span></span>
<span class="line"><span style="color:#D19A66;">       blocking</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">query</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> blocking_query</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_activity blocked</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> pg_locks blocked_locks </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> blocked</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> pg_locks blocking_locks</span></span>
<span class="line"><span style="color:#C678DD;">    ON</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">locktype</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> blocking_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">locktype</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">database</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> DISTINCT</span><span style="color:#C678DD;"> FROM</span><span style="color:#D19A66;"> blocking_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">database</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">relation</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> DISTINCT</span><span style="color:#C678DD;"> FROM</span><span style="color:#D19A66;"> blocking_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">relation</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">page</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> DISTINCT</span><span style="color:#C678DD;"> FROM</span><span style="color:#D19A66;"> blocking_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">page</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">tuple</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> DISTINCT</span><span style="color:#C678DD;"> FROM</span><span style="color:#D19A66;"> blocking_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">tuple</span></span>
<span class="line"><span style="color:#C678DD;">    AND</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span><span style="color:#56B6C2;"> !=</span><span style="color:#D19A66;"> blocking_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> pg_stat_activity blocking </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> blocking_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> blocking</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">pid</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> NOT</span><span style="color:#D19A66;"> blocked_locks</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">granted</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="pg-locks-视图" tabindex="-1"><a class="header-anchor" href="#pg-locks-视图"><span>pg_locks 视图</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看当前所有锁</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> locktype,</span></span>
<span class="line"><span style="color:#C678DD;">       database</span><span style="color:#ABB2BF;">::regclass,</span></span>
<span class="line"><span style="color:#ABB2BF;">       relation::regclass,</span></span>
<span class="line"><span style="color:#ABB2BF;">       pid,</span></span>
<span class="line"><span style="color:#ABB2BF;">       mode,</span></span>
<span class="line"><span style="color:#ABB2BF;">       granted</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_locks</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> pid </span><span style="color:#56B6C2;">!=</span><span style="color:#ABB2BF;"> pg_backend_pid()</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> pid, locktype;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 常用：查看被阻塞的会话</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pid,</span></span>
<span class="line"><span style="color:#ABB2BF;">       usename,</span></span>
<span class="line"><span style="color:#ABB2BF;">       application_name,</span></span>
<span class="line"><span style="color:#ABB2BF;">       wait_event_type,</span></span>
<span class="line"><span style="color:#ABB2BF;">       wait_event,</span></span>
<span class="line"><span style="color:#ABB2BF;">       query,</span></span>
<span class="line"><span style="color:#C678DD;">       state</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_activity</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> wait_event_type </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;Lock&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span> pid  | wait_event_type | wait_event |              query</span></span>
<span class="line"><span>------+-----------------+------------+----------------------------------</span></span>
<span class="line"><span> 1234 | Lock            | relation   | ALTER TABLE users ADD COLUMN ...</span></span>
<span class="line"><span> 1235 | Lock            | tuple      | UPDATE accounts SET balance ...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="咨询锁-advisory-locks" tabindex="-1"><a class="header-anchor" href="#咨询锁-advisory-locks"><span>咨询锁（Advisory Locks）</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 咨询锁：应用级分布式锁，与数据无关</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 适合：跨进程互斥、限流、分布式锁</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话级锁（随会话释放）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_advisory_lock(</span><span style="color:#D19A66;">12345</span><span style="color:#ABB2BF;">);          </span><span style="color:#7F848E;font-style:italic;">-- 获取锁（阻塞等待）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_try_advisory_lock(</span><span style="color:#D19A66;">12345</span><span style="color:#ABB2BF;">);      </span><span style="color:#7F848E;font-style:italic;">-- 尝试获取（立即返回 bool）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_advisory_unlock(</span><span style="color:#D19A66;">12345</span><span style="color:#ABB2BF;">);        </span><span style="color:#7F848E;font-style:italic;">-- 释放锁</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务级锁（随事务结束释放）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_advisory_xact_lock(</span><span style="color:#D19A66;">12345</span><span style="color:#ABB2BF;">);     </span><span style="color:#7F848E;font-style:italic;">-- 事务内有效</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- COMMIT / ROLLBACK 后自动释放</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 使用两个 int4 作为 key</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_advisory_lock(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">);         </span><span style="color:#7F848E;font-style:italic;">-- (1, 100) 组合键</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_advisory_unlock(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 使用 int8 作为 key</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pg_advisory_lock(</span><span style="color:#D19A66;">123456789012345</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">咨询锁实战：防止重复执行</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 定时任务防重入</span></span>
<span class="line"><span style="color:#C678DD;">CREATE OR REPLACE</span><span style="color:#C678DD;"> FUNCTION</span><span style="color:#61AFEF;"> run_daily_report</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#C678DD;">RETURNS</span><span style="color:#ABB2BF;"> void </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> $$</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 尝试获取锁，失败说明已有实例在执行</span></span>
<span class="line"><span style="color:#C678DD;">    IF</span><span style="color:#C678DD;"> NOT</span><span style="color:#ABB2BF;"> pg_try_advisory_xact_lock(</span><span style="color:#D19A66;">20250604</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">THEN</span></span>
<span class="line"><span style="color:#ABB2BF;">        RAISE NOTICE </span><span style="color:#98C379;">&#39;Report already running&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        RETURN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    END</span><span style="color:#C678DD;"> IF</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 执行报表逻辑</span></span>
<span class="line"><span style="color:#C678DD;">    INSERT INTO</span><span style="color:#ABB2BF;"> daily_reports (</span><span style="color:#C678DD;">date</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">data</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> CURRENT_DATE, json_agg(row_to_json(daily_stats))</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> daily_stats</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> report_date </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> CURRENT_DATE;</span></span>
<span class="line"><span style="color:#C678DD;">END</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">$$ </span><span style="color:#C678DD;">LANGUAGE</span><span style="color:#ABB2BF;"> plpgsql;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>咨询锁的优势：不依赖表数据，性能好，适合分布式场景。</p></div><h2 id="实战-并发订单处理" tabindex="-1"><a class="header-anchor" href="#实战-并发订单处理"><span>实战：并发订单处理</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 场景：电商高并发下单，防止超卖</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> products</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id       </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;">     text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    stock    </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    CONSTRAINT</span><span style="color:#ABB2BF;"> positive_stock </span><span style="color:#C678DD;">CHECK</span><span style="color:#ABB2BF;"> (stock </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> products (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, stock) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;限量球鞋&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 错误写法：先查后改，有超卖风险</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> stock </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 读到 stock=10</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- （另一个事务也读到 10，都认为够卖）</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> stock - </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 卖了两次！</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 方案 1：原子 UPDATE + 检查</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> stock - </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#ABB2BF;">RETURNING *;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 如果返回 0 行，说明库存不足</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 方案 2：SELECT FOR UPDATE 锁行</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> stock </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 锁行</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> stock - </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 方案 3：SKIP LOCKED 并发安全扣减</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> products </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> stock - </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#C678DD;">AND</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> stock </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 1</span></span>
<span class="line"><span style="color:#C678DD;">    FOR</span><span style="color:#C678DD;"> UPDATE</span><span style="color:#C678DD;"> SKIP</span><span style="color:#ABB2BF;"> LOCKED</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">RETURNING *;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频问题</p><ol><li><p><strong>PG 的行锁存在哪里？</strong></p><ul><li>不在磁盘存储！利用 tuple 的 xmax 字段标记</li><li>好处：无需额外锁表空间，行锁数量无限制</li><li>代价：锁信息随事务结束丢失（不可跨事务查询锁历史）</li></ul></li><li><p><strong>FOR UPDATE 的四种模式？</strong></p><ul><li><code>FOR UPDATE</code>：最强排他锁</li><li><code>FOR NO KEY UPDATE</code>：弱排他，不阻塞 FOR KEY SHARE</li><li><code>FOR SHARE</code>：共享锁</li><li><code>FOR KEY SHARE</code>：最弱，仅锁外键引用列</li></ul></li><li><p><strong>SKIP LOCKED 有什么用？</strong></p><ul><li>并发任务分配、工作队列的最佳选择</li><li>跳过已锁行，返回可用行</li><li>不保证公平性（可能饥饿），但保证无阻塞</li></ul></li><li><p><strong>咨询锁和普通锁的区别？</strong></p><ul><li>咨询锁：应用定义语义，与数据无关，不会自动释放（除非用 xact 版本）</li><li>普通锁：PG 自动管理，事务结束释放</li><li>咨询锁适合分布式互斥，普通锁适合数据一致性</li></ul></li><li><p><strong>如何避免死锁？</strong></p><ul><li>固定加锁顺序（总是先锁 id 小的行）</li><li>减少事务持锁时间</li><li>使用 NOWAIT/SKIP LOCKED 替代无限等待</li></ul></li></ol></div><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://www.postgresql.org/docs/16/explicit-locking.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - Explicit Locking</a></li><li><a href="https://www.postgresql.org/docs/16/view-pg-locks.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - pg_locks</a></li><li><a href="https://www.postgresql.org/docs/16/explicit-locking.html#ADVISORY-LOCKS" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - Advisory Locks</a></li><li><a href="https://github.com/supabase/supabase" target="_blank" rel="noopener noreferrer">Supabase GitHub</a></li></ul>`,14)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};